<?php
require_once dirname(__DIR__,3).'/bootstrap.php';$allowedRoles=[ROLE_ADMIN];require APP_ROOT.'/app/middleware/RoleMiddleware.php';use App\Services\FirebaseService;
$id=sanitize($_GET['id']??$_POST['id']??'');$permission=FirebaseService::getInstance()->getDocument(COL_PERMISSIONS,$id);if(!$permission){flash('error','Permission matrix not found.');redirect(url('views/admin/permissions/index.php'));}$levels=$permission['levels']??[];$modules=['users','students','houses','rooms','attendance','visitors','incidents','reports'];if($_SERVER['REQUEST_METHOD']==='POST'){$updated=[];foreach($modules as $module)$updated[$module]=sanitize($_POST[$module]??'none');FirebaseService::getInstance()->updateDocument(COL_PERMISSIONS,$id,['levels'=>$updated,'updatedBy'=>current_user()['uid']??current_user()['id']??'admin']);flash('success','Permission matrix updated.');redirect(url('views/admin/permissions/index.php'));}$pageTitle='Edit Permission';$navItems=[['icon'=>'bi-key','label'=>'Permissions','href'=>url('views/admin/permissions/index.php'),'active'=>true]];require APP_ROOT.'/app/views/components/header.php';require APP_ROOT.'/app/views/components/sidebar.php';?>
<div class="main-content"><?php require APP_ROOT.'/app/views/components/navbar.php';?><div class="content-wrapper"><div class="card stat-card p-4" style="max-width:820px"><h5 class="mb-3">Edit <?=e(ucwords(str_replace('_',' ',$id)))?> permissions</h5><form method="POST"><input type="hidden" name="id" value="<?=e($id)?>"><div class="table-responsive"><table class="table table-bordered"><thead><tr><th>Module</th><th>Access level</th></tr></thead><tbody><?php foreach($modules as $module):?><tr><td><?=e(ucfirst($module))?></td><td><select name="<?=e($module)?>" class="form-select"><option value="none" <?=($levels[$module]??'none')==='none'?'selected':''?>>None</option><option value="view" <?=($levels[$module]??'')==='view'?'selected':''?>>View</option><option value="manage" <?=($levels[$module]??'')==='manage'?'selected':''?>>Manage</option><option value="full" <?=($levels[$module]??'')==='full'?'selected':''?>>Full</option><option value="own" <?=($levels[$module]??'')==='own'?'selected':''?>>Own</option></select></td></tr><?php endforeach;?></tbody></table></div><button class="btn btn-primary">Save changes</button> <a class="btn btn-outline-secondary" href="<?=url('views/admin/permissions/index.php')?>">Cancel</a></form></div></div></div><?php require APP_ROOT.'/app/views/components/footer.php';?>